// Seed Challenges array construction
const CHALLENGES = [];

for (const category of CATEGORIES) {
  const problems = RAW_PROBLEMS_BY_CATEGORY[category] || [];
  for (let i = 0; i < problems.length; i++) {
    const raw = problems[i];
    const difficulty = raw.difficulty;
    const fnName = raw.fnName;
    const title = raw.title;
    
    // Pick 2-4 random companies
    const companies = pickRandom(COMPANIES_POOL, Math.floor(Math.random() * 3) + 2);
    
    // Base templates
    const jsTemplate = `function ${fnName}${raw.inputs[0].split(',')[0].includes('[') ? `(nums` : `(s`}${raw.inputs[0].includes(',') ? `, target` : ``}) {\n  // Write your code here\n  \n}`;
    const pyTemplate = `def ${fnName.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`)}(${raw.inputs[0].split(',')[0].includes('[') ? `nums` : `s`}${raw.inputs[0].includes(',') ? `, target` : ``}):\n    # Write your code here\n    pass`;
    const javaTemplate = `public class Solution {\n    public Object ${fnName}(${raw.inputs[0].split(',')[0].includes('[') ? `int[] nums` : `String s`}${raw.inputs[0].includes(',') ? `, int target` : ``}) {\n        // Write your code here\n        return null;\n    }\n}`;
    const cppTemplate = `class Solution {\npublic:\n    auto ${fnName}(${raw.inputs[0].split(',')[0].includes('[') ? `vector<int>& nums` : `string s`}${raw.inputs[0].includes(',') ? `, int target` : ``}) {\n        // Write your code here\n        \n    }\n};`;
    const cTemplate = `// C Function signature\nvoid ${fnName}(void) {\n    // Write your code here\n}`;

    CHALLENGES.push({
      title,
      description: `${raw.desc}\n\n### Sample Input\n\`${raw.inputs[0]}\`\n\n### Expected Output\n\`${raw.outputs[0]}\`\n\n### Constraints\n- Time Complexity expectation: ${difficulty === 'Easy' ? 'O(N)' : 'O(N log N)'}\n- Space Complexity expectation: O(N) or O(1)`,
      difficulty,
      category,
      companyTags: companies,
      codeTemplates: {
        javascript: jsTemplate,
        python: pyTemplate,
        java: javaTemplate,
        cpp: cppTemplate,
        c: cTemplate
      },
      testCases: [
        { input: raw.inputs[0], expectedOutput: raw.outputs[0], isHidden: false },
        { input: raw.inputs[1], expectedOutput: raw.outputs[1], isHidden: false },
        { input: raw.inputs[2] || raw.inputs[0], expectedOutput: raw.outputs[2] || raw.outputs[0], isHidden: true }
      ],
      solution: {
        timeComplexity: difficulty === 'Easy' ? 'O(N)' : 'O(N log N)',
        spaceComplexity: difficulty === 'Hard' ? 'O(N)' : 'O(1)',
        explanation: raw.explanation
      }
    });
  }
}

module.exports = {
  CHALLENGES
};
